+/////////////////////////////////////////////////////////////////////// Side //
+
+enum Side
+{
+    SideIn   = -1,
+    SideZero = +0,
+    SideOut  = +1
+};
+
+INLINE_H_D Side cicToSide( RealType det )
+{
+    return ( det < 0 ) ? SideOut : ( ( det > 0 ) ? SideIn : SideZero );
+}
