+__global__ void kerMakeFirstTri
+(
+Tri*	triArr,
+TriOpp*	oppArr,
+char*	triInfoArr,
+Tri*     initTri,
+int     infIdx
+)
+{
+    Tri tri = initTri[0];
+
+    const Tri tris[] = {
+        { tri._v[0], tri._v[1], tri._v[2] },
+        { tri._v[2], tri._v[1], infIdx },
+        { tri._v[0], tri._v[2], infIdx },
+        { tri._v[1], tri._v[0], infIdx }
+    };
+
+    const int oppTri[][3] = {
+        { 1, 2, 3 },
+        { 3, 2, 0 },
+        { 1, 3, 0 },
+        { 2, 1, 0 }
+    };
+
+    const int oppVi[][4] = {
+        { 2, 2, 2 },
+        { 1, 0, 0 },
+        { 1, 0, 1 },
+        { 1, 0, 2 }
