+        oppArr[ i ] = opp;
+    }
+}
+
+__device__ const int SplitFaces[6][3] = {
+    /*0*/ { 0, 3 },
+    /*1*/ { 2, 3 },                   /*2*/ { 1, 3 },
+    /*3*/ { 1, 2 },  /*4*/ { 2, 0 },  /*5*/ { 0, 1 }
+};
+
+__device__ const int SplitNext[6][2] = {
+    { 1, 2 },
+    { 3, 4 },               { 5, 3 },
+    { 1, 0 },   { 2, 0 },   { 3, 0 },
+};
