+__global__ void
+kerMakeCompactMap
+(
+char*        triInfoVec,
+int          nTriInfo,
+int*         prefixArr,
+int*         freeArr,
+int          newTriNum
+)
+{
+    for ( int idx = newTriNum + getCurThreadIdx();
