+__global__ void
+kerCompactTris
+(
+char*        triInfoVec,
+int          nTriInfo,
+int*         prefixArr,
+Tri*         triArr,
+TriOpp*      oppArr,
+int          newTriNum
+)
+{
+    for ( int idx = newTriNum + getCurThreadIdx();
+          idx < nTriInfo; idx += getThreadNum() )
+    {
+        int newTriIdx = prefixArr[ idx ];
+
+        if ( newTriIdx == -1 ) continue;
+
+        triArr[ newTriIdx ]          = triArr[ idx ];
+        triInfoVec[ newTriIdx ] = triInfoVec[ idx ];
