+#include <cupy/math_constants.h>
+#define MAX_SZ 1024
+
+extern "C" __global__ void reduce_peaks(
+        const int row_idx,
+        const int gap_thresh,
+        const double* __restrict__ max_distances,
+        const long long* __restrict__ rows,
+        const long long* __restrict__ peaks_cols,
